const basket = await BasketModel.findByPk(req.params.id);
if (!basket) return res.status(404).send('Basket not found');
if (basket.UserId !== req.user.id && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Access Denied: You do not own this basket' });
